svg.script:

function ip9Init(svg){
  "use strict";
  if(!svg || (svg.tagName && svg.tagName.toLowerCase() !== 'svg')) return;
  if(svg.getAttribute('data-ip9-wired') === '1') return;
  svg.setAttribute('data-ip9-wired','1');

  var doc = svg.ownerDocument || document;
  var win = doc.defaultView || window;

  var TONE = {
    cyan:'#22d3ee', good:'#34d399', warn:'#f59e0b', err:'#fb7185',
    fat:'#22d3ee', res:'#38bdf8', amb:'#60a5fa', ill:'#818cf8', loss:'#a78bfa'
  };

  function esc(s){
    return String(s).replace(/[&<>"']/g, function(c){
      if(c === '&') return '&amp;';
      if(c === '<') return '&lt;';
      if(c === '>') return '&gt;';
      if(c === '"') return '&quot;';
      return '&#39;';
    });
  }

  var tip = doc.createElement('div');
  tip.setAttribute('role','status');
  tip.setAttribute('aria-live','polite');
  tip.style.cssText = [
    'position:fixed','z-index:2147483000','max-width:360px','pointer-events:none',
    'opacity:0','transform:translateY(6px)','transition:opacity .14s ease, transform .14s ease',
    'background:linear-gradient(180deg, rgba(18,28,46,.985), rgba(8,14,26,.985))',
    'border:1px solid rgba(103,232,249,0.30)','border-radius:14px','padding:14px 16px',
    'box-shadow:0 22px 58px -14px rgba(0,0,0,.82)',
    'backdrop-filter:blur(16px)','-webkit-backdrop-filter:blur(16px)',
    'color:#c7d2e0','font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text",Inter,"Segoe UI",system-ui,sans-serif',
    'left:0','top:0'
  ].join(';');
  (doc.body || doc.documentElement).appendChild(tip);

  var active = null;

  function setTip(label, hint, text, hex){
    tip.innerHTML =
      '<span style="display:inline-flex;align-items:center;gap:9px;margin-bottom:8px">' +
        '<span style="min-width:24px;height:24px;padding:0 7px;border-radius:12px;display:inline-flex;align-items:center;justify-content:center;font-size:12.5px;font-weight:800;color:#0b1220;background:' + hex + '">' + esc(label) + '</span>' +
        '<span style="font-size:13.5px;font-weight:700;color:#f2f6fc">' + esc(hint) + '</span>' +
      '</span>' +
      '<p style="font-size:13px;line-height:1.56;color:#c7d2e0;margin:0">' + esc(text) + '</p>';
  }

  function placeTip(ev, g){
    var pad = 14;
    var tw = tip.offsetWidth || 340;
    var th = tip.offsetHeight || 150;
    var x, y;
    if(ev && typeof ev.clientX === 'number'){
      x = ev.clientX + 18; y = ev.clientY + 18;
    } else {
      var r = g.getBoundingClientRect();
      x = r.left + r.width/2 - tw/2; y = r.top - th - 12;
      if(y < pad) y = r.bottom + 12;
    }
    x = Math.max(pad, Math.min(x, win.innerWidth - tw - pad));
    y = Math.max(pad, Math.min(y, win.innerHeight - th - pad));
    tip.style.left = x + 'px';
    tip.style.top = y + 'px';
  }

  function showTip(ev, g, data){
    active = g;
    g.setAttribute('data-active','1');
    setTip(data.label, data.hint, data.text, data.hex);
    placeTip(ev, g);
    tip.style.opacity = '1';
    tip.style.transform = 'translateY(0)';
  }

  function hideTip(g){
    if(g){ g.removeAttribute('data-active'); }
    if(!g || active === g){
      tip.style.opacity = '0';
      tip.style.transform = 'translateY(6px)';
      active = null;
    }
  }

  function dataOf(g){
    return {
      label: g.getAttribute('data-hs-label') || g.getAttribute('data-crit') || '',
      hint:  g.getAttribute('data-hs-hint') || '',
      text:  g.getAttribute('data-hs-text') || '',
      hex:   TONE[g.getAttribute('data-hs-tone')] || TONE.cyan
    };
  }

  var pureShapes = Array.prototype.slice.call(svg.querySelectorAll('.ip9-hs'));
  pureShapes.forEach(function(g){
    var data = dataOf(g);
    g.setAttribute('tabindex','0');
    g.setAttribute('role','button');
    g.setAttribute('aria-label', data.hint + '. ' + data.text);
    g.addEventListener('mouseenter', function(ev){ showTip(ev, g, data); });
    g.addEventListener('mousemove', function(ev){ if(active === g) placeTip(ev, g); });
    g.addEventListener('mouseleave', function(){ hideTip(g); });
    g.addEventListener('focus', function(){ showTip(null, g, data); });
    g.addEventListener('blur', function(){ hideTip(g); });
    g.addEventListener('click', function(ev){ ev.stopPropagation(); if(active === g){ hideTip(g); } else { showTip(ev, g, data); } });
    g.addEventListener('keydown', function(ev){
      if(ev.key === 'Enter' || ev.key === ' '){ ev.preventDefault(); if(active === g){ hideTip(g); } else { showTip(null, g, data); } }
      if(ev.key === 'Escape'){ hideTip(g); if(g.blur) g.blur(); }
    });
    g.addEventListener('touchstart', function(ev){ ev.stopPropagation(); if(active === g){ hideTip(g); } else { showTip(null, g, data); } }, {passive:true});
  });

  var readNum = svg.querySelector('#ip9ReadNum');
  var readLbl = svg.querySelector('#ip9ReadLbl');
  var pointer = svg.querySelector('#ip9Pointer');
  var zones = Array.prototype.slice.call(svg.querySelectorAll('.ip9-zone'));
  var crits = Array.prototype.slice.call(svg.querySelectorAll('.ip9-crit'));
  var ZONEX = { R:798, P:1036, F:1352 };
  var ZONECOL = { R:TONE.good, P:TONE.warn, F:TONE.err };

  var live = doc.createElement('div');
  live.setAttribute('aria-live','polite');
  live.style.cssText = 'position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap';
  (doc.body || doc.documentElement).appendChild(live);

  function recompute(){
    var on = 0;
    crits.forEach(function(c){ if(c.getAttribute('data-on') === '1') on++; });
    var zone, cls;
    if(on === 0){ zone='R'; cls='robusto'; }
    else if(on <= 2){ zone='P'; cls='pré-frágil'; }
    else { zone='F'; cls='frágil'; }
    if(readNum){ readNum.textContent = on + ' / 5'; readNum.setAttribute('fill', ZONECOL[zone]); }
    if(readLbl){ readLbl.textContent = cls; readLbl.setAttribute('fill', ZONECOL[zone]); }
    if(pointer){
      pointer.setAttribute('transform', 'translate(' + ZONEX[zone] + ',0)');
      var tri = pointer.querySelector('path');
      if(tri){ tri.setAttribute('fill', ZONECOL[zone]); }
    }
    zones.forEach(function(z){ z.classList.toggle('ip9-zone-active', z.getAttribute('data-zone') === zone); });
    live.textContent = 'FRAIL ' + on + ' de 5: ' + cls;
  }

  crits.forEach(function(g){
    var data = dataOf(g);
    g.setAttribute('aria-label', data.hint + '. ' + data.text);
    function toggle(){
      var now = g.getAttribute('data-on') === '1' ? '0' : '1';
      g.setAttribute('data-on', now);
      g.setAttribute('aria-pressed', now === '1' ? 'true' : 'false');
      recompute();
    }
    g.addEventListener('mouseenter', function(ev){ showTip(ev, g, data); });
    g.addEventListener('mousemove', function(ev){ if(active === g) placeTip(ev, g); });
    g.addEventListener('mouseleave', function(){ hideTip(g); });
    g.addEventListener('focus', function(){ showTip(null, g, data); });
    g.addEventListener('blur', function(){ hideTip(g); });
    g.addEventListener('click', function(ev){ ev.stopPropagation(); toggle(); });
    g.addEventListener('keydown', function(ev){
      if(ev.key === 'Enter' || ev.key === ' '){ ev.preventDefault(); toggle(); }
      if(ev.key === 'Escape'){ hideTip(g); if(g.blur) g.blur(); }
    });
    g.addEventListener('touchstart', function(ev){ ev.stopPropagation(); ev.preventDefault(); toggle(); showTip(null, g, data); }, {passive:false});
  });

  doc.addEventListener('click', function(){ if(active){ hideTip(active); } });
  win.addEventListener('scroll', function(){ if(active){ tip.style.opacity = '0'; } }, {passive:true});

  recompute();
}

(function(){
  "use strict";
  var me = (typeof document !== 'undefined') ? document.currentScript : null;
  var s = me ? (me.ownerSVGElement || me.parentNode) : null;
  while(s && s.tagName && s.tagName.toLowerCase() !== 'svg'){ s = s.parentNode; }
  if(s){ ip9Init(s); return; }
  function scan(){
    var list = document.querySelectorAll('svg[aria-labelledby="ip9Ttl ip9Dsc"]:not([data-ip9-wired="1"])');
    for(var i=0;i<list.length;i++){ ip9Init(list[i]); }
  }
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', scan);
  }
  if(typeof Promise !== 'undefined'){ Promise.resolve().then(scan); }
  else { setTimeout(scan, 0); }
})();
